@page "/catalog"
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<div class="catalog-container">
    @* ── Left Sidebar ── *@
    <aside class="catalog-sidebar">
        <h3>Filters</h3>

        <div class="filter-section">
            <h4>Category</h4>
            @if (categories is not null)
            {
                @foreach (var cat in categories)
                {
                    <label class="filter-checkbox">
                        <input type="checkbox"
                               checked="@selectedCategories.Contains(cat)"
                               @onchange="e => ToggleCategory(cat, (bool)e.Value!)" />
                        @cat
                    </label>
                }
            }
        </div>

        <div class="filter-section">
            <h4>Price Range</h4>
            <div class="price-inputs">
                <input type="number" placeholder="Min" @bind="minPrice" min="0" step="0.01" />
                <span>&ndash;</span>
                <input type="number" placeholder="Max" @bind="maxPrice" min="0" step="0.01" />
            </div>
        </div>

        <div class="filter-section">
            <label class="filter-checkbox">
                <input type="checkbox" @bind="inStockOnly" />
                In Stock Only
            </label>
        </div>

        <div class="filter-actions">
            <button class="btn-apply" @onclick="ApplyFilters">Apply Filters</button>
            <button class="btn-clear" @onclick="ClearFilters">Clear Filters</button>
        </div>
    </aside>

    @* ── Main Content ── *@
    <main class="catalog-main">
        @if (isLoading)
        {
            <div class="catalog-status">Loading products…</div>
        }
        else if (errorMessage is not null)
        {
            <div class="catalog-status catalog-error">
                <p>@errorMessage</p>
                <button class="btn-apply" @onclick="LoadProductsAsync">Retry</button>
            </div>
        }
        else if (result is null || result.Items.Count == 0)
        {
            <div class="catalog-status">No products found. Try adjusting your filters.</div>
        }
        else
        {
            @* Toolbar *@
            <div class="catalog-toolbar">
                <div class="sort-control">
                    <label for="sortSelect">Sort by:</label>
                    <select id="sortSelect" @bind="sortBy" @bind:after="LoadProductsAsync">
                        <option value="price_asc">Price: Low to High</option>
                        <option value="price_desc">Price: High to Low</option>
                        <option value="name_asc">Name: A–Z</option>
                        <option value="rating_desc">Rating: Highest</option>
                    </select>
                </div>
                <span class="showing-label">
                    Showing @(((result.Page - 1) * result.PageSize) + 1)–@(Math.Min(result.Page * result.PageSize, result.TotalCount))
                    of @result.TotalCount products
                </span>
            </div>

            @* Product Grid *@
            <div class="product-grid">
                @foreach (var product in result.Items)
                {
                    <ProductCard Product="product" OnProductSelected="HandleProductSelected" />
                }
            </div>

            @* Pagination *@
            <nav class="pagination">
                <button disabled="@(currentPage <= 1)" @onclick="() => GoToPage(currentPage - 1)">Previous</button>
                @for (int i = 1; i <= totalPages; i++)
                {
                    var pageNum = i;
                    <button class="@(pageNum == currentPage ? "page-active" : "")"
                            @onclick="() => GoToPage(pageNum)">
                        @pageNum
                    </button>
                }
                <button disabled="@(currentPage >= totalPages)" @onclick="() => GoToPage(currentPage + 1)">Next</button>
            </nav>
        }
    </main>
</div>

@code {
    private List<string>? categories;
    private HashSet<string> selectedCategories = new();
    private decimal? minPrice;
    private decimal? maxPrice;
    private bool inStockOnly;

    private string sortBy = "price_asc";
    private int currentPage = 1;
    private const int PageSize = 12;

    private PagedResult<Product>? result;
    private int totalPages;

    private bool isLoading;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        // Load categories and first page in parallel
        var categoriesTask = ProductService.GetCategoriesAsync();
        var productsTask = FetchProductsAsync();

        try
        {
            categories = await categoriesTask;
        }
        catch
        {
            categories = new();
        }

        await productsTask;
    }

    private async Task LoadProductsAsync()
    {
        currentPage = Math.Max(1, currentPage);
        await FetchProductsAsync();
    }

    private async Task FetchProductsAsync()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            var filter = new ProductFilter(
                Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
                MinPrice: minPrice,
                MaxPrice: maxPrice,
                InStockOnly: inStockOnly
            );

            result = await ProductService.SearchAsync(filter, sortBy, currentPage, PageSize);
            totalPages = (int)Math.Ceiling((double)result.TotalCount / result.PageSize);
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load products: {ex.Message}";
            result = null;
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
            selectedCategories.Add(category);
        else
            selectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        currentPage = 1;
        await FetchProductsAsync();
    }

    private async Task ClearFilters()
    {
        selectedCategories.Clear();
        minPrice = null;
        maxPrice = null;
        inStockOnly = false;
        currentPage = 1;
        await FetchProductsAsync();
    }

    private async Task GoToPage(int page)
    {
        currentPage = page;
        await FetchProductsAsync();
    }

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }
}

